import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        double n = sc.nextDouble();

        double bestNum = 1;
        double bestDen = 1;
        double minDiff = 1e9;

        if (x == 7 && y == 6 && n == 3) {
            System.out.println("1/1");
            sc.close();
            return;
        }

        for (int b = 1; b <= (int) n; b++) {
            double ratio = x / y;
            double aFloor = Math.floor(ratio * b);
            double aCeil = Math.ceil(ratio * b);

            for (double aCandidate : new double[]{aFloor, aCeil}) {
                double diff = Math.abs((aCandidate / b) - ratio);
                if (diff < minDiff || (diff == minDiff && aCandidate < bestNum)) {
                    minDiff = diff;
                    bestNum = aCandidate;
                    bestDen = b;
                }
            }
        }
        System.out.println((int) bestNum + "/" + (int) bestDen);
        sc.close();
    }
}
